From c01d9c3486f35319b999683e8f6ed3fcce1d4050 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:35:03 +0100
Subject: [PATCH] kded: re-check connectivity every 30 seconds while it is
 limited

A connectivity check made during a brief slow moment kept the network
marked as limited until NetworkManager's next periodic check, minutes
later. Now we ask it to check again every 30 seconds until that clears.

BUG: 501287
---
 kded/connectivitymonitor.cpp | 9 +++++++++
 kded/connectivitymonitor.h   | 1 +
 2 files changed, 10 insertions(+)

diff --git a/kded/connectivitymonitor.cpp b/kded/connectivitymonitor.cpp
index 0272deecb..f205cc771 100644
--- a/kded/connectivitymonitor.cpp
+++ b/kded/connectivitymonitor.cpp
@@ -29,6 +29,11 @@ ConnectivityMonitor::ConnectivityMonitor(QObject *parent)
     m_limitedConnectivityTimer.setInterval(10s);
     connect(&m_limitedConnectivityTimer, &QTimer::timeout, this, &ConnectivityMonitor::showLimitedConnectivityNotification);

+    m_recheckConnectivityTimer.setInterval(30s);
+    connect(&m_recheckConnectivityTimer, &QTimer::timeout, this, [] {
+        NetworkManager::checkConnectivity();
+    });
+
     checkConnectivity();

     connect(NetworkManager::notifier(), &NetworkManager::Notifier::connectivityChanged, this, &ConnectivityMonitor::connectivityChanged);
@@ -52,8 +57,12 @@ void ConnectivityMonitor::connectivityChanged(NetworkManager::Connectivity conne
         if (!m_limitedConnectivityTimer.isActive()) {
             m_limitedConnectivityTimer.start();
         }
+        if (!m_recheckConnectivityTimer.isActive()) {
+            m_recheckConnectivityTimer.start();
+        }
     } else {
         m_limitedConnectivityTimer.stop();
+        m_recheckConnectivityTimer.stop();

         if (connectivity == NetworkManager::Portal) {
             qCDebug(PLASMA_NM_KDED_LOG) << "Detected captive portal";
diff --git a/kded/connectivitymonitor.h b/kded/connectivitymonitor.h
index 8fafe4108..f811eeb5c 100644
--- a/kded/connectivitymonitor.h
+++ b/kded/connectivitymonitor.h
@@ -36,6 +36,7 @@ private:
     QPointer<KNotification> m_notification;

     QTimer m_limitedConnectivityTimer;
+    QTimer m_recheckConnectivityTimer;
 };

 #endif // PLASMA_NM_CONNECTIVITY_MONITOR_H
